<?php $this->assign('title', 'Profissionais'); ?><div class="d-flex justify-content-between mb-4"><h1 class="h3">Profissionais</h1><?= $this->Html->link('Novo profissional', ['action' => 'add'], ['class' => 'btn btn-primary']) ?></div><div class="card border-0 shadow-sm"><table class="table table-hover mb-0"><thead><tr><th>Nome</th><th>Tipo</th><th>Especialidade</th><th>Registro</th><th></th></tr></thead><tbody><?php foreach ($profissionais as $profissional): ?><tr><td><?= h($profissional->nome) ?></td><td><?= h($profissional->tipo) ?></td><td><?= h($profissional->especialidade->nome ?? '-') ?></td><td><?= h($profissional->registro_profissional ?: '-') ?></td><td><?= $this->Html->link('Editar', ['action' => 'edit', $profissional->id], ['class' => 'btn btn-sm btn-outline-primary']) ?> <?= $this->Form->postLink('Inativar', ['action' => 'inativar', $profissional->id], ['class' => 'btn btn-sm btn-outline-danger', 'confirm' => 'Inativar profissional?']) ?></td></tr><?php endforeach; ?></tbody></table></div>
